#include "darc.h"
#include <string.h>
static const uint32_t K[64]={
0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u};
static uint32_t rr(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
static uint32_t be32(const uint8_t*p){return((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
static void block(DarcSha256*c,const uint8_t*p){uint32_t w[64];for(int i=0;i<16;i++)w[i]=be32(p+4*i);for(int i=16;i<64;i++){uint32_t a=w[i-15],b=w[i-2];uint32_t s0=rr(a,7)^rr(a,18)^(a>>3),s1=rr(b,17)^rr(b,19)^(b>>10);w[i]=w[i-16]+s0+w[i-7]+s1;}uint32_t a=c->h[0],b=c->h[1],d=c->h[3],e=c->h[4],f=c->h[5],g=c->h[6],h=c->h[7],cc=c->h[2];for(int i=0;i<64;i++){uint32_t S1=rr(e,6)^rr(e,11)^rr(e,25),ch=(e&f)^((~e)&g),t1=h+S1+ch+K[i]+w[i],S0=rr(a,2)^rr(a,13)^rr(a,22),maj=(a&b)^(a&cc)^(b&cc),t2=S0+maj;h=g;g=f;f=e;e=d+t1;d=cc;cc=b;b=a;a=t1+t2;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=cc;c->h[3]+=d;c->h[4]+=e;c->h[5]+=f;c->h[6]+=g;c->h[7]+=h;}
void darc_sha256_init(DarcSha256*c){static const uint32_t h[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};memcpy(c->h,h,sizeof h);c->bits=0;c->used=0;}
void darc_sha256_update(DarcSha256*c,const void*vp,size_t n){const uint8_t*p=vp;c->bits+=(uint64_t)n*8u;while(n){size_t k=64-c->used;if(k>n)k=n;memcpy(c->block+c->used,p,k);c->used+=k;p+=k;n-=k;if(c->used==64){block(c,c->block);c->used=0;}}}
void darc_sha256_final(DarcSha256*c,uint8_t out[32]){uint64_t bits=c->bits;c->block[c->used++]=0x80;if(c->used>56){memset(c->block+c->used,0,64-c->used);block(c,c->block);c->used=0;}memset(c->block+c->used,0,56-c->used);for(int i=0;i<8;i++)c->block[63-i]=(uint8_t)(bits>>(8*i));block(c,c->block);for(int i=0;i<8;i++){out[4*i]=(uint8_t)(c->h[i]>>24);out[4*i+1]=(uint8_t)(c->h[i]>>16);out[4*i+2]=(uint8_t)(c->h[i]>>8);out[4*i+3]=(uint8_t)c->h[i];}}
void darc_sha256(const void*p,size_t n,uint8_t out[32]){DarcSha256 c;darc_sha256_init(&c);darc_sha256_update(&c,p,n);darc_sha256_final(&c,out);}
